//! Clipboard history (E10). Off by default. Memory only (never disk, never
//! logs), wiped on stop and on `Clear`; only short previews are published.
//! Polls `NSPasteboard.changeCount` (no content) every 0.5 s while running
//! and reads the contents only when it changed AND macOS paste privacy is
//! "Always allow" — otherwise each read would show the system alert.
//! Concealed / transient / auto-generated copies (password managers) and
//! copies made while an excluded app is frontmost are never recorded.

use crate::sys::pasteboard::{Access, Board, Content};
use crate::sys::{MAIN_TIMEOUT, on_main};
use crossbeam_channel::{Receiver, Sender, select, unbounded};
use nox_core::model::clipboard::{
    ClipEntry, ClipKind, ClipboardCommand, ClipboardSettings, ClipboardState,
};
use nox_core::permissions::PermissionState;
use nox_core::{CancelToken, Hub, Module, ModuleContext, ModuleError, ModuleId, Settings, Worker};
use objc2_app_kit::NSWorkspace;
use std::collections::VecDeque;
use std::sync::Arc;
use std::time::Duration;

const POLL: Duration = Duration::from_millis(500);
const PREVIEW_CHARS: usize = 200;
const MAX_ITEMS_CAP: usize = 100;

/// Types marking content that must never be recorded
/// (http://nspasteboard.org and 1Password's historical marker).
pub const IGNORED_TYPES: &[&str] = &[
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
];

enum Msg {
    Command(ClipboardCommand),
    Settings(Arc<Settings>),
}

#[derive(Default)]
pub struct ClipboardModule {
    worker: Option<Worker>,
    tx: Option<Sender<Msg>>,
}

impl Module for ClipboardModule {
    fn id(&self) -> ModuleId {
        ModuleId::Clipboard
    }

    fn start(&mut self, ctx: ModuleContext) -> Result<(), ModuleError> {
        self.stop();
        let (tx, rx) = unbounded();
        let hub = ctx.hub.clone();
        let settings = ctx.settings.clipboard.clone();
        hub.update(|s| s.clipboard = Some(ClipboardState::default()));
        self.worker = Some(Worker::spawn("clipboard", move |token| {
            run(hub, settings, rx, token)
        }));
        self.tx = Some(tx);
        Ok(())
    }

    fn stop(&mut self) {
        self.tx.take();
        if let Some(mut w) = self.worker.take() {
            w.stop();
        }
    }

    fn command(&mut self, cmd: nox_core::Command) {
        if let (nox_core::Command::Clipboard(c), Some(tx)) = (cmd, &self.tx) {
            let _ = tx.send(Msg::Command(c));
        }
    }

    fn settings_changed(&mut self, settings: &Arc<Settings>) {
        if let Some(tx) = &self.tx {
            let _ = tx.send(Msg::Settings(settings.clone()));
        }
    }
}

pub fn permission(a: Access) -> PermissionState {
    match a {
        Access::AlwaysAllow => PermissionState::Granted,
        Access::Default => PermissionState::NotDetermined,
        Access::Ask | Access::AlwaysDeny => PermissionState::Denied,
    }
}

/// Never record: marked types, or an excluded app in front.
pub fn ignored(types: &[String], frontmost: Option<&str>, s: &ClipboardSettings) -> bool {
    types.iter().any(|t| IGNORED_TYPES.contains(&t.as_str()))
        || frontmost.is_some_and(|f| s.excluded_apps.iter().any(|e| e.eq_ignore_ascii_case(f)))
}

fn shorten(s: &str) -> String {
    let flat: String = s.split_whitespace().collect::<Vec<_>>().join(" ");
    let mut out: String = flat.chars().take(PREVIEW_CHARS).collect();
    if flat.chars().count() > PREVIEW_CHARS {
        out.push('…');
    }
    out
}

/// (kind, preview, byte length) of a content.
pub fn describe(c: &Content) -> (ClipKind, String, usize) {
    match c {
        Content::Text(t) => (ClipKind::Text, shorten(t), t.len()),
        Content::Url(u) => (ClipKind::Url, shorten(u), u.len()),
        Content::Files(f) => {
            let names: Vec<&str> = f
                .iter()
                .map(|p| p.rsplit('/').next().unwrap_or(p))
                .collect();
            (
                ClipKind::Files(f.len()),
                shorten(&names.join(", ")),
                f.iter().map(String::len).sum(),
            )
        }
        Content::Image { data, .. } => (ClipKind::Image, "Image".into(), data.len()),
    }
}

/// In-memory history: previews published, contents kept here only.
#[derive(Default)]
pub struct History {
    items: VecDeque<(ClipEntry, Content)>,
    next_id: u64,
}

impl History {
    /// Records a copy (moves an identical one to the top).
    pub fn push(&mut self, c: Content, source: Option<String>, now: f64, max: usize) {
        self.items.retain(|(_, x)| *x != c);
        self.next_id += 1;
        let (kind, preview, byte_len) = describe(&c);
        self.items.push_front((
            ClipEntry {
                id: self.next_id,
                kind,
                preview,
                source_app: source,
                copied_at: now,
                byte_len,
            },
            c,
        ));
        self.items.truncate(max.clamp(1, MAX_ITEMS_CAP));
    }
    pub fn get(&self, id: u64) -> Option<&Content> {
        self.items.iter().find(|(e, _)| e.id == id).map(|(_, c)| c)
    }
    pub fn remove(&mut self, id: u64) {
        self.items.retain(|(e, _)| e.id != id);
    }
    pub fn clear(&mut self) {
        self.items.clear();
    }
    pub fn entries(&self) -> Vec<ClipEntry> {
        self.items.iter().map(|(e, _)| e.clone()).collect()
    }
}

fn frontmost() -> Option<String> {
    NSWorkspace::sharedWorkspace()
        .frontmostApplication()
        .and_then(|a| a.bundleIdentifier())
        .map(|s| s.to_string())
}

/// One snapshot of the general pasteboard, on the main thread.
struct Read {
    count: i64,
    access: Access,
    /// Present only when the contents were read.
    content: Option<(Vec<String>, Option<Content>, Option<String>)>,
}

fn poll(last: i64, force_read: bool, s: &ClipboardSettings) -> Option<Read> {
    let (max, images) = (s.max_bytes_per_item, s.capture_images);
    on_main(MAIN_TIMEOUT, move || {
        let b = Board::general();
        let count = b.change_count();
        let access = b.access();
        let content = ((count != last && access == Access::AlwaysAllow) || force_read)
            .then(|| (b.types(), b.read(max, images), frontmost()));
        Read {
            count,
            access,
            content,
        }
    })
}

fn run(hub: Hub, mut settings: ClipboardSettings, rx: Receiver<Msg>, token: CancelToken) {
    let mut history = History::default();
    let mut state = ClipboardState::default();
    // The current contents predate the module: never imported.
    let mut last = poll(i64::MIN, false, &settings)
        .map(|r| r.count)
        .unwrap_or(0);
    let publish = |state: &ClipboardState| {
        let s = state.clone();
        hub.update(move |st| {
            if st.clipboard.is_some() {
                st.clipboard = Some(s);
            }
        });
    };
    let mut force_read = false;
    while !token.is_cancelled() {
        if let Some(r) = poll(last, force_read, &settings) {
            force_read = false;
            let access = permission(r.access);
            let mut changed = access != state.access;
            state.access = access;
            if let Some((types, content, front)) = r.content
                && r.count != last
                && !ignored(&types, front.as_deref(), &settings)
                && let Some(c) = content
            {
                history.push(c, front, nox_core::model::now(), settings.max_items);
                changed = true;
            }
            last = r.count;
            if changed {
                state.items = history.entries();
                publish(&state);
            }
        }
        select! {
            recv(rx) -> m => match m {
                Ok(Msg::Command(c)) => {
                    match c {
                        ClipboardCommand::Restore(id) => {
                            if let Some(c) = history.get(id).cloned() {
                                // Our own write must not come back as a new copy.
                                if let Some(n) = on_main(MAIN_TIMEOUT, move || Board::general().write(&c)).flatten() {
                                    last = n;
                                }
                            }
                        }
                        ClipboardCommand::Remove(id) => history.remove(id),
                        ClipboardCommand::Clear => history.clear(),
                        // A user action: one read so macOS can ask once.
                        ClipboardCommand::RequestAccess => force_read = true,
                    }
                    state.items = history.entries();
                    publish(&state);
                }
                Ok(Msg::Settings(s)) => {
                    settings = s.clipboard.clone();
                    let max = settings.max_items.clamp(1, MAX_ITEMS_CAP);
                    history.items.truncate(max);
                    state.items = history.entries();
                    publish(&state);
                }
                Err(_) => break,
            },
            default(POLL) => {},
        }
    }
    history.clear();
    hub.update(|s| s.clipboard = None);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ignores_concealed_and_excluded() {
        let s = ClipboardSettings::default();
        let t = |v: &[&str]| v.iter().map(|x| x.to_string()).collect::<Vec<_>>();
        assert!(ignored(
            &t(&["public.utf8-plain-text", "org.nspasteboard.ConcealedType"]),
            None,
            &s
        ));
        assert!(ignored(
            &t(&["public.utf8-plain-text"]),
            Some("com.1password.1password"),
            &s
        ));
        assert!(!ignored(
            &t(&["public.utf8-plain-text"]),
            Some("com.apple.TextEdit"),
            &s
        ));
    }

    #[test]
    fn history_dedupes_caps_and_previews() {
        let mut h = History::default();
        for i in 0..5 {
            h.push(
                Content::Text(format!("synthetic {i}")),
                None,
                f64::from(i),
                3,
            );
        }
        assert_eq!(h.entries().len(), 3, "capped");
        assert_eq!(h.entries()[0].preview, "synthetic 4");
        h.push(Content::Text("synthetic 2".into()), None, 9.0, 3);
        let e = h.entries();
        assert_eq!(
            e[0].preview, "synthetic 2",
            "identical copy moves to the top"
        );
        assert_eq!(e.len(), 3);
        let long = "x".repeat(500);
        h.push(Content::Text(long.clone()), None, 10.0, 3);
        assert_eq!(h.entries()[0].preview.chars().count(), PREVIEW_CHARS + 1);
        assert_eq!(h.get(h.entries()[0].id), Some(&Content::Text(long)));
        let (k, p, _) = describe(&Content::Files(vec!["/a/b.pdf".into(), "/c/d.png".into()]));
        assert_eq!((k, p.as_str()), (ClipKind::Files(2), "b.pdf, d.png"));
        h.clear();
        assert!(h.entries().is_empty());
    }

    #[test]
    fn private_pasteboard_roundtrip_and_markers() {
        // A uniquely named pasteboard: the user's clipboard is never touched.
        let b = Board::unique();
        assert_eq!(
            b.access(),
            Access::AlwaysAllow,
            "named pasteboards always allow"
        );
        let n0 = b.change_count();
        let n1 = b.write(&Content::Text("synthetic text".into())).unwrap();
        assert!(n1 > n0);
        assert_eq!(
            b.read(1 << 20, false),
            Some(Content::Text("synthetic text".into()))
        );
        assert_eq!(b.read(4, false), None, "over max_bytes");
        b.write(&Content::Files(vec![
            "/tmp/synthetic-a".into(),
            "/tmp/synthetic-b".into(),
        ]));
        assert_eq!(
            b.read(1 << 20, false),
            Some(Content::Files(vec![
                "/tmp/synthetic-a".into(),
                "/tmp/synthetic-b".into()
            ]))
        );
        b.write(&Content::Url("https://example.org/x".into()));
        assert_eq!(
            b.read(1 << 20, false),
            Some(Content::Url("https://example.org/x".into()))
        );
        b.write(&Content::Text("secret".into()));
        assert!(b.add_marker("org.nspasteboard.ConcealedType"));
        assert!(ignored(&b.types(), None, &ClipboardSettings::default()));
        b.release();
    }
}
